import hashlib,json

def load_release(index, body):
    if hashlib.sha256(body).hexdigest() != index['sha256']:
        raise ValueError('payload_checksum_mismatch')
    rows=json.loads(body)
    if not isinstance(rows,list) or any(type(r.get('id')) is not int for r in rows):
        raise ValueError('invalid_rows')
    if len(rows) != index['advertised_count']:
        raise ValueError('listing_count_drift')
    return {'rows':rows,'audit':{'advertised':index['advertised_count'],'actual':len(rows),'count_difference':0}}

